import logging
from ..exceptions import ProhibitedInstanceError, MbmsSessionVerificationFailure
from ..config import loggers as ute_ue_logging


class MbmsSession:
    """Object responsible for managing mbms session"""

    def __init__(self, service_name, configuration, logger_name='ute_ue'):
        """
        :param configuration:
        :param service_name:
        """
        self.name = service_name
        if self.__class__.__name__ == 'MbmsSession':
            raise ProhibitedInstanceError("you can't create instance of MbmsSession base class, use derived ones")
        self._configuration = configuration
        if 'ue_logger_name' in self._configuration:
            raw_logger = logging.getLogger(self._configuration['ue_logger_name'])
        else:
            raw_logger = logging.getLogger(logger_name)
        self.logger = ute_ue_logging.LoggerAdapter4EmptyExtra(raw_logger, {'area': 'MBMS'})

    def start_verifying(self):
        """
        Starts verifying mbsm session
        :return: None
        """
        raise NotImplementedError

    def stop_verifying(self):
        """
        Stops verifying mbms session

        Fires exception if given mbms session (selected by it's name) was not listened yet.
        No action if given mbms session is not listened
        :return: None
        """
        raise NotImplementedError

    def is_being_verified(self):
        """
        Check if mbms session is being verified

        :return: boolean
        """
        raise NotImplementedError

    def verify_success_rate_with_deviation(self, success_rate, deviation):
        """
        Verify if success rate is in desired range: success_rate-(success_rate*deviation) <-> success_rate+(success_rate*deviation)

        :param success_rate: desired success_rate in string format (expressed in percentages) e.g. '90%'
        :param deviation: acceptable deviation (expressed in percentages) from desired success_rate. e.g '5%'
        :return: Nonell
        :raises MbmsSessionVerificationFailure: if verification fails
        """
        expected_success_rate = self._parse_percentage(success_rate)
        success_rate_as_float = self.get_success_rate()
        deviation_as_float = self._parse_percentage(deviation) / 100
        min_threshold = expected_success_rate - (expected_success_rate * deviation_as_float)
        max_threshold = expected_success_rate + (expected_success_rate * deviation_as_float)
        if success_rate_as_float < min_threshold or success_rate_as_float > max_threshold:
            raise MbmsSessionVerificationFailure(f'expected success rate range:min={min_threshold} <-> max={max_threshold}, actual success rate'
                                                 f' success rate={success_rate_as_float} [%]')

    def verify_success_rate(self, success_rate_min, success_rate_max=None):
        """
        Verify if success rate is in desired range: success rate_min <-> success rate_max
        If success_rate_max=None: Verify if success rate  is above desired threshold: success_rate_min

        :param success_rate_min: lower threshold for desired success rate in string format. e.g. '90%'
        :param success_rate_max: upper threshold for desired success rate in string format. e.g. '100%'
        :return: None
        :raises MbmsSessionVerificationFailure: if verification fails
        """
        success_rate_as_float = self.get_success_rate()
        normalized_success_rate_min = self._parse_percentage(success_rate_min)
        if success_rate_as_float < normalized_success_rate_min:
            msg = f'expected success_rate_min={normalized_success_rate_min}, actual success_rate={success_rate_as_float} [%]'
            raise MbmsSessionVerificationFailure(msg)
        if success_rate_max and success_rate_as_float > self._parse_percentage(success_rate_max):
            msg = f'expected success_rate_min={normalized_success_rate_min}' \
                        f' and success_rate_max={self._parse_percentage(success_rate_max)},' \
                        f' actual success_rate={success_rate_as_float} [%]'
            raise MbmsSessionVerificationFailure(msg)

    def get_success_rate(self):
        """
        Abstract method for getting success rate of mbms session.
        success rate is measured from 'mbms_session.start_listening()' to current time or
        from 'mbms_session.start_listening()' to 'mbms_session.stop_listening()' if mbms session listening is finished
        :return: success rate in unit: %
        """
        raise NotImplementedError

    def reset_statistics(self):
        """
        Abstract method for resetting statistics of mbms session.
        :return: None
        """
        raise NotImplementedError

    def _parse_percentage(self, unparsed_percentage):
        number = unparsed_percentage.rstrip('%')
        percentage_as_float = float(number)
        return percentage_as_float
